#region Easy Settings
$PathIdNumberPip = "01"
# The number or string [Any number or string] added to the folder name when being created! (Useful to edit if running more than one Pip!)

$PathIdNumberRandom = "0"
# Does not replace (0) or does replace (1) the number or string added to the folder name with a random number! (Useful to edit if you want to have muliple of Pip at once, though it might make a lot of folders!)

$CreateOrOverwriteFilesOrImages = "1" 
# Stop (0) or continue (1) overwriting the files in the folder! (Useful to edit if customizing the look of Pip!)

$StopAndGoToPath = "0"
# Does not (0) or does (1) stop the script midway, to close and open the path to the folder! (Useful to edit if trying to go to the path to customize Pip!)

$ModifierName = "0"
# Does not (0) or does [Anything other than 0] include your name in the credits so people knw you modified this Pip script, replace the 0 with your name! (Useful to edit to let people know you modified this!)

$BackgroundWindowColor = "White"
# Changes [Anything in the color list] the color of the window's background! (Useful to give your script some difference!)

$TextWindowColor = "Black"
# Changes [Anything in the color list] the color of the window's text! (Useful to make your text more readable on your colored background!)

$VoicePitchness = 7
# Changes {Any number between -10 and 10} how squeaky Pip's voice is, or the pitch! (Useful to edit to change your character of Pip!)

$VoiceVolume = 60
# Changes {Any number between 0 and 100} how loud Pip's voice is, or the volume! (Useful to edit when Pip has to be quiet or loud!)

$VoiceSpeed = 1
# Changes {Any number between -10 and 10} how fast Pip's voice is, or the rate! (Useful to edit when Pip has to have a fast or quiet voice!)

$PipName = "Pip the Mochi"
# Changes [Anything, or any string] the name, which desplays in the terminal when Pip is loaded! (Useful to edit so people know what character you changed Pip into, or what Pip is!)

$PipSize = 3
# Changes {Any number greater than 0} the size, or scale, of Pip, 1 is the original resolution! (Useful to edit if Pip seems too small or too big!)

$BorderThickness = 0
# Changes {Any number 0 or greater} the thickness, or size, of the border around Pip, 0 makes no border! (Useful to edit if the border is too small or too big, you do not want the border, or if the image already has a border, which is true for the default image!)

$PipShakeHardness = 100
# Changes {Any number 0 or greater} how hard it is for Pip to become dizzy from the shaking! (Useful to edit if Pip is too easy or too hard to become dizzy!)

$AllowEatting = "1"
# Does not (0) or does (1) allow Pip to delete, or eat, files when dragged into Pip! (Useful to edit if you want or don't want Pip to be able to eat files!)
#endregion

