try {
    # 1. LOAD REQUIRED CORE LIBRARIES
    Add-Type -AssemblyName PresentationFramework
    Add-Type -AssemblyName PresentationCore
    Add-Type -AssemblyName WindowsBase
} catch {
    # If the GUI libraries fail to load, we have to fall back to a standard console error
    Write-Error "Critical Windows GUI libraries could not be loaded: $_"
    pause ; start powershell "-NoExit Write-Host Do not want this window to type commands? Try typing exit instead! You have gotten this window from errors. ; Write-host Seems like the libraries could not load, are you using Windows 10 or 11? ; cd C:\PipTheMochi$($PathIdNumberPip)" ; exit
}

if ($PathIdNumberRandom -eq "1") {
    $PathIdNumberPip = Get-Random
}

try {
    New-Item -ItemType Directory -Force -Path "C:\PipTheMochi$($PathIdNumberPip)" -ErrorAction Stop
} catch {    
