    pause ; start powershell "-NoExit Write-Host Do not want this window to type commands? Try typing exit instead! You have gotten this window from errors. ; Write-host Seems like the folder could not be created, if you are running with the right permissions, try closing all the windows that have ran Pip before, and try running Pip again! ; cd C:\PipTheMochi$($PathIdNumberPip)" ; exit
}

