try {
    # 1. Manually instantiate a pure WPF Window object (Zero XAML Strings)
    $window = New-Object System.Windows.Window
    $window.WindowStyle = [System.Windows.WindowStyle]::None
    $window.AllowsTransparency = $true
    $window.Background = [System.Windows.Media.Brushes]::Transparent
    $window.Topmost = $true
    $window.SizeToContent = [System.Windows.SizeToContent]::WidthAndHeight
    $window.Left = 100
    $window.Top = 100

    # 2. Create the TextBlock object directly in memory
    $textControl = New-Object System.Windows.Controls.TextBlock
    $textControl.Text = ""
    $textControl.FontSize = 22
    $textControl.Foreground = [System.Windows.Media.Brushes]::White
    $textControl.FontWeight = [System.Windows.FontWeights]::SemiBold
    $textControl.TextAlignment = [System.Windows.TextAlignment]::Center
    $textControl.VerticalAlignment = [System.Windows.VerticalAlignment]::Top
    $textControl.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
    $textControl.TextWrapping = [System.Windows.TextWrapping]::Wrap
    $textControl.MaxWidth = 450
    $textControl.Visibility = [System.Windows.Visibility]::Collapsed

    # Add a text shadow effect for clarity over bright backgrounds
    $TextShadow = New-Object System.Windows.Media.Effects.DropShadowEffect
    $TextShadow.Color = [System.Windows.Media.Color]::FromRgb(0, 0, 0)
    $TextShadow.BlurRadius = 4
    $TextShadow.ShadowDepth = 3
    $TextShadow.Opacity = 0.8
    $textControl.Effect = $TextShadow
} catch {
    $Decision = [System.Windows.MessageBox]::Show("Text object could not be created, Pip The Mochi failed!", "System Error", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error)
    pause ; start powershell "-NoExit Write-Host Do not want this window to type commands? Try typing exit instead! You have gotten this window from errors. ; Write-host Seems like the text object could not be loaded or created, are you using Windows 10 or 11? ; cd C:\PipTheMochi$($PathIdNumberPip)" ; exit
}

