function Get-RandomLine ($Action) {
    $Pool = $Script:DialoguePool[$Action]
    return $Pool[(Get-Random -Minimum 0 -Maximum $Pool.Count)]
}

# 3. EXTRA HIGH-PITCH HARDWARE-ISOLATED BACKGROUND SPEECH ENGINE SETUP
$Script:SpeechBox = [hashtable]::Synchronized(@{ Text = ""; Trigger = 0 })
$Script:SpeechRunspace = [PowerShell]::Create().AddScript({
    param($Box, $Pitchness, $Volume, $Rate) # Added $Rate here
    
    $Voice = New-Object -ComObject SAPI.SpVoice
    $Voice.Volume = $Volume
    $Voice.Rate = $Rate # Set the speed cleanly upon initialization
    
    $VoicesAvailable = $Voice.GetVoices()
    if ($VoicesAvailable.Count -gt 1) {
        $Voice.Voice = $VoicesAvailable.Item(1)
    }
    
    $LastTrigger = 0
    while ($true) {
        if ($Box.Trigger -ne $LastTrigger) {
            $LastTrigger = $Box.Trigger
            $TextToSay = $Box.Text
            if ($TextToSay) {
                $XmlFormattedSpeech = "<pitch middle='$Pitchness'/>" + $TextToSay
                $null = $Voice.Speak($XmlFormattedSpeech, 11)
            }
        }
        Start-Sleep -Milliseconds 10
    }
# CRITICAL: Added $VoiceRate to the end of the argument chain in exact matching sequence
}).AddArgument($Script:SpeechBox).AddArgument($VoicePitchness).AddArgument($VoiceVolume).AddArgument($VoiceSpeed) 
$Script:SpeechAsyncResult = $Script:SpeechRunspace.BeginInvoke()

function Say-Text ($Text) {
    if ($Script:IsMuted) { return }

    if ($Text) {
        $Script:SpeechBox.Text = $Text
        $Script:SpeechBox.Trigger++
        
        # Reset text visibility and push speech data to the subtitle layout frame
        $Script:textControl.Text = $Text
        $Script:textControl.Visibility = [System.Windows.Visibility]::Visible
        
        # Keep text visible for 7.5 seconds whenever a new sentence triggers
        $Script:TextHideCountdown = 7500
    }
}

# 4. CLEAN ASSET LOAD FUNCTION
function Get-CleanWpfImage ($Path) {
    if (-not (Test-Path $Path)) { return $null }
    $BitmapImage = New-Object System.Windows.Media.Imaging.BitmapImage
    $BitmapImage.BeginInit()
    $BitmapImage.UriSource = [System.Uri]$Path
    $BitmapImage.EndInit()
    return $BitmapImage
}

